<script setup>
defineProps({ model: Object });
</script>
<template>
  <template v-if="model.data">
    <details v-for="[title, kind] in [['調整遠征隊時間', 'time'], ['變更遠征隊名稱', 'name'], ['複製遠征隊', 'copy'], ['設定圖釘', 'pins'], ['更改遠征隊隱私', 'privacy']]" :key="kind" class="room-setting"><summary>{{ title }}</summary><form :data-room-form="kind">
      <template v-if="kind === 'time'"><label for="room-event-date">開始日期（可不指定）</label><input id="room-event-date" name="event_date" type="date" :value="model.data.room.event_date"><label for="room-event-end-date">結束日期（可選）</label><input id="room-event-end-date" name="event_end_date" type="date" :value="model.data.room.event_end_date || ''" :min="model.data.room.event_date" aria-describedby="room-date-range-note"><p id="room-date-range-note" class="field-note">單日活動只填開始日期；多日活動再選擇結束日期。</p><label for="room-event-time">開始時間（可選）</label><input id="room-event-time" name="event_time" type="time" :value="model.data.event_time"><label for="room-time-zone">時區</label><select id="room-time-zone" name="time_zone" :value="model.data.time_zone"><option value="Asia/Tokyo">日本時間（UTC+9）</option><option value="Asia/Taipei">台灣時間（UTC+8）</option></select></template>
      <template v-else-if="kind === 'name'"><label for="room-name-input">遠征隊名稱</label><input id="room-name-input" name="name" required maxlength="60" :value="model.data.room.name"><p class="field-note">1–60 個字</p></template>
      <template v-else-if="kind === 'copy'"><label for="room-copy-name">新遠征隊名稱</label><input id="room-copy-name" name="name" required maxlength="60" :value="[...model.data.room.name].slice(0, 55).join('') + '（副本）'"><p class="field-note">沿用會場、時間、隱私、加入密碼與圖釘設定。新隊伍只有你，使用新的邀請碼。</p></template>
      <template v-else-if="kind === 'pins'"><label for="room-pin-policy">放置方式</label><select id="room-pin-policy" name="pin_policy" :value="model.data.pin_policy"><option value="free">自由放置</option><option value="approval">審核放置</option></select><p class="field-note">審核放置的圖釘，須經團長或副團長核准才會出現在地圖上。既有待審圖釘仍需審核。</p><button type="button" class="button outline full" data-room-submissions>審核圖釘</button></template>
      <template v-else><label for="room-privacy">加入方式</label><select id="room-privacy" name="privacy" :value="model.data.privacy"><option value="public">公開：可從場館列表加入</option><option value="password">密碼：輸入密碼才能加入</option><option value="invite">邀請：僅使用邀請碼加入</option></select><div data-room-password :hidden="model.data.privacy !== 'password'"><label for="room-join-password">{{ model.data.has_password ? '新加入密碼（留空保留原密碼）' : '加入密碼' }}</label><input id="room-join-password" name="password" type="password" minlength="8" maxlength="128" autocomplete="new-password" :disabled="model.data.privacy !== 'password'"><p class="field-note">8–128 個字元。密碼隊伍仍會出現在場館列表。</p></div><p class="field-note">變更只影響後續加入，既有成員會保留。</p></template>
      <p class="form-error" role="alert"></p><button class="button secondary" type="submit">{{ kind === 'copy' ? '建立複本' : '儲存' }}</button>
    </form></details>
  </template>
  <div class="room-management-actions"><button v-if="model.leader" type="button" class="button outline full logout-button" data-room-danger="delete">解散遠征隊</button><p v-if="model.data?.joined === false" class="field-note">目前未加入這支遠征隊。</p><button v-else type="button" class="button outline full" data-room-danger="leave">退出遠征隊</button></div><div data-room-confirm hidden></div>
</template>
